const retryWorkflowExecutionAction = `-- name: RetryWorkflowExecutionAction :execrows
UPDATE workflow_execution_action
SET status = 'pending', claim_token = NULL, lease_until = NULL,
    available_at = $4, last_error = $5, updated_at = now()
WHERE workspace_id = $1 AND id = $2 AND claim_token = $3
  AND status = 'leased' AND lease_until > now()
`

type RetryWorkflowExecutionActionParams struct {
	WorkspaceID pgtype.UUID        `json:"workspace_id"`
	ID          pgtype.UUID        `json:"id"`
	ClaimToken  pgtype.UUID        `json:"claim_token"`
	AvailableAt pgtype.Timestamptz `json:"available_at"`
	LastError   pgtype.Text        `json:"last_error"`
}

func (q *Queries) RetryWorkflowExecutionAction(ctx context.Context, arg RetryWorkflowExecutionActionParams) (int64, error) {
	result, err := q.db.Exec(ctx, retryWorkflowExecutionAction,
		arg.WorkspaceID,
		arg.ID,
		arg.ClaimToken,
		arg.AvailableAt,
		arg.LastError,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
